<?= ff('text', 'approved_by', 'pol.approved_by', '', ['hint' => t('pol.approved_hint')]) ?><?= ff('date', 'approval_date', 'pol.approval_date', '') ?>
<?= ff('textarea', 'change_summary', 'pol.change_summary', '', ['wide' => true]) ?>
